mapper.select:
SELECT * FROM skill

    is_deleted = 0
    AND type = #{type}

ORDER BY id DESC LIMIT #{offset}, #{limit}

mapper.update:
UPDATE skill SET name = #{name}, type = #{type}, install_spec = #{installSpec},
    description = #{description}, version = version + 1, modifier_id = #{modifierId}
WHERE id = #{id} AND tenant_id = #{tenantId} AND version = #{version} AND is_deleted = 0
